/**
 * "Learn wxKanban with your AI" — read-only routes. SCOPE-138 / T011 (FR-010).
 *
 *   GET /api/help/teaching-skills         what the current bundle holds (signed-in)
 *   GET /api/help/teaching-skills/bundle  the zip: start-here.md and the lessons (signed-in)
 *
 * GET only. The lessons are generated by /wxHelpGenerate --teach as part of each release.
 */
import { Router, Response } from "express";
import { authenticateToken, requireAuth, AuthRequest } from "~/server/middleware/auth.js";
import { bundleInfo, buildBundle } from "~/server/services/TeachingBundleService.js";
import { createLogger } from "~/server/lib/logger.js";

const router = Router();
const logger = createLogger("teaching-skills-routes");

// [SCOPE 138 / T011] BEGIN — Teaching bundle summary and download (FR-010)
router.get("/", authenticateToken, requireAuth, (_req: AuthRequest, res: Response) => {
  res.status(200).json(bundleInfo());
});

router.get("/bundle", authenticateToken, requireAuth, (req: AuthRequest, res: Response) => {
  const bundle = buildBundle();
  if (!bundle) {
    res.status(404).json({ error: "The teaching bundle has not been generated for this release yet." });
    return;
  }
  logger.info({ userid: req.userid, file: bundle.fileName, bytes: bundle.data.length }, "[teaching-skills] bundle downloaded");
  res.setHeader("Content-Type", "application/zip");
  res.setHeader("Content-Disposition", `attachment; filename="${bundle.fileName}"`);
  res.status(200).send(bundle.data);
});
// [SCOPE 138 / T011] END

export default router;
